# Fuzz: compare handler against a naive reference on a fresh store (catalog changes
# mid-stream are NOT allowed per README, so only add orders/sessions after start).
import random
from infra.store import Store, Auth
from service import handler

rng = random.Random(7)
store, auth = Store(), Auth(store)
P, C = 12, 5
data = {}
for k in range(P):
    data["product:%d" % k] = {"name": "p%03d" % k, "price_cents": rng.randint(100, 9000)}
    data["discount:%d" % k] = {"percent_off": rng.choice([0, 5, 10, 15, 25])}
for k in range(C):
    data["customer:%d" % k] = {"name": "c%03d" % k}
store._load(data)

def ref(order, user):
    lines, total = [], 0
    for it in order["items"]:
        p, d = data["product:%d" % it["product_id"]], data["discount:%d" % it["product_id"]]
        amt = p["price_cents"] * it["quantity"] * (100 - d["percent_off"]) // 100
        total += amt
        lines.append({"name": p["name"], "amount": amt})
    return {"user": user, "customer": data["customer:%d" % order["customer_id"]]["name"],
            "lines": lines, "total_cents": total}

for i in range(300):
    order = {"customer_id": rng.randrange(C),
             "items": [{"product_id": c, "quantity": rng.randint(1, 5)}
                       for c in rng.sample(range(P), rng.randint(1, 5))]}
    store._load({"order:%d" % i: order})
    tok, user = "t%d" % i, "u%d" % i
    auth._add(tok, user)
    got = handler.handle(store, auth, {"token": tok, "order_id": i})
    exp = ref(order, user)
    assert got == exp, (i, got, exp)
print("fuzz OK: 300/300 responses identical")
EOF

