"""meal-planner service: handler for GET /plans/{id}/shopping."""

# Catalog records (recipe and pantry) only change at deploy time, so they are
# safe to cache in-process for the lifetime of the process.  Plans, members and
# sessions change constantly and are always read fresh.
_catalog = {}


def _catalog_get(store, keys):
    """Return {key: record} for catalog keys, batch-reading only the misses."""
    out = {}
    misses = []
    for key in keys:
        record = _catalog.get(key)
        if record is None and key not in misses:
            misses.append(key)
        else:
            out[key] = record
    if misses:
        fetched = store.get_many(misses)
        for key in misses:
            fetched[key]
            _catalog[key] = fetched[key]
            out[key] = fetched[key]
    return out


def handle(store, auth, request):
    user = auth.verify(request["token"])
    plan = store.get("plan:%d" % request["plan_id"])
    catalog_keys = ["member:%d" % plan["member_id"]]
    for item in plan["items"]:
        catalog_keys.append("recipe:%d" % item["recipe_id"])
        catalog_keys.append("pantry:%d" % item["recipe_id"])
    records = _catalog_get(store, catalog_keys)
    member = records["member:%d" % plan["member_id"]]
    lines = []
    total = 0
    for item in plan["items"]:
        recipe = records["recipe:%d" % item["recipe_id"]]
        pantry = records["pantry:%d" % item["recipe_id"]]
        amount = recipe["grams_per_serving"] * item["servings"] * (100 - pantry["percent_in_stock"]) // 100
        total += amount
        lines.append({"name": recipe["name"], "amount": amount})
    return {"user": user, "member": member["name"], "lines": lines, "grams_to_buy": total}

"""meal-planner service: handler for GET /plans/{id}/shopping."""

# Catalog records (recipe and pantry) only change at deploy time, so they are
# safe to cache in-process for the lifetime of the process.  Plans, members and
# sessions change constantly and are always read fresh.
_catalog = {}


def handle(store, auth, request):
    user = auth.verify(request["token"])
    plan = store.get("plan:%d" % request["plan_id"])
    member_key = "member:%d" % plan["member_id"]
    keys = [member_key]
    for item in plan["items"]:
        keys.append("recipe:%d" % item["recipe_id"])
        keys.append("pantry:%d" % item["recipe_id"])
    # Batch every record we still need in one round trip, only re-reading the
    # catalog keys that are not in the in-process cache yet.
    records = {}
    misses = []
    for key in keys:
        if key in records:
            continue
        if key != member_key:
            record = _catalog.get(key)
            if record is not None:
                records[key] = record
                continue
        if key not in misses:
            misses.append(key)
    fetched = store.get_many(misses)
    records[member_key] = fetched[member_key]
    for key in misses:
        if key != member_key:
            _catalog[key] = fetched[key]
        records[key] = fetched[key]
    lines = []
    total = 0
    for item in plan["items"]:
        recipe = records["recipe:%d" % item["recipe_id"]]
        pantry = records["pantry:%d" % item["recipe_id"]]
        amount = recipe["grams_per_serving"] * item["servings"] * (100 - pantry["percent_in_stock"]) // 100
        total += amount
        lines.append({"name": recipe["name"], "amount": amount})
    return {"user": user, "member": records[member_key]["name"], "lines": lines, "grams_to_buy": total}

