"""itineraries service: handler for GET /trips/{id}/quote."""

# Catalogue records (legs and fare rules) only change at deploy time, so an
# in-process cache stays valid for the lifetime of the process (a deploy
# restarts it). Trips, travellers and sessions are created all the time, so
# they are still fetched from the store on every request.
_LEG_CACHE = {}
_FARE_CACHE = {}


def _load_catalogue(store, leg_ids):
    """Fetch any legs / fare rules not yet cached, in a single round trip."""
    missing_legs = {k for k in leg_ids if k not in _LEG_CACHE}
    missing_fares = {k for k in leg_ids if k not in _FARE_CACHE}
    if not missing_legs and not missing_fares:
        return
    keys = ["leg:%d" % k for k in missing_legs] + \
           ["fare_rule:%d" % k for k in missing_fares]
    for key, record in store.get_many(keys).items():
        if key.startswith("leg:"):
            _LEG_CACHE[int(key[4:])] = record
        else:
            _FARE_CACHE[int(key[9:])] = record


def handle(store, auth, request):
    user = auth.verify(request["token"])
    trip = store.get("trip:%d" % request["trip_id"])
    traveller = store.get("traveller:%d" % trip["traveller_id"])
    leg_ids = [item["leg_id"] for item in trip["items"]]
    _load_catalogue(store, leg_ids)
    lines = []
    total = 0
    for item in trip["items"]:
        leg = _LEG_CACHE[item["leg_id"]]
        fare_rule = _FARE_CACHE[item["leg_id"]]
        amount = leg["fare_cents"] * item["seats"] * (100 - fare_rule["rebate_percent"]) // 100
        total += amount
        lines.append({"name": leg["name"], "amount": amount})
    return {"user": user, "traveller": traveller["name"], "lines": lines, "quote_cents": total}

