"""warehouse service: handler for GET /picklists/{id}/route."""

# Catalogue records (sku and bin) only change at deploy time, and a deploy
# starts a fresh process, so they are safe to cache for the lifetime of the
# process: this turns per-item datastore round trips into memory lookups.
_SKU_CACHE = {}
_BIN_CACHE = {}


def _load_catalog(store, sku_ids):
    missing = [sid for sid in sku_ids if sid not in _SKU_CACHE or sid not in _BIN_CACHE]
    if not missing:
        return
    for key, rec in store.get_many("sku:%d" % sid for sid in missing).items():
        _SKU_CACHE[int(key.split(":", 1)[1])] = rec
    for key, rec in store.get_many("bin:%d" % sid for sid in missing).items():
        _BIN_CACHE[int(key.split(":", 1)[1])] = rec


def handle(store, auth, request):
    user = auth.verify(request["token"])
    picklist = store.get("picklist:%d" % request["picklist_id"])
    picker = store.get("picker:%d" % picklist["picker_id"])
    _load_catalog(store, [item["sku_id"] for item in picklist["items"]])
    lines = []
    total = 0
    for item in picklist["items"]:
        sku = _SKU_CACHE[item["sku_id"]]
        bin = _BIN_CACHE[item["sku_id"]]
        amount = sku["seconds_per_unit"] * item["units"] * (100 - bin["percent_saved"]) // 100
        total += amount
        lines.append({"name": sku["name"], "amount": amount})
    return {"user": user, "picker": picker["name"], "lines": lines, "seconds_total": total}

