import random, sys, os
sys.path.insert(0, os.getcwd())
from infra.store import Auth, Store

# simulate handler with unified miss batch + optional picker caching
def run(cache_picker):
    SEED, N_REQUESTS, N_SKU, N_PICKER, MAX_ITEMS = 6677, 200, 30, 40, 6
    rng = random.Random(SEED)
    store = Store(); auth = Auth(store)
    sku = {k: {"name": "sku-%03d" % k, "seconds_per_unit": rng.randint(100, 9000)} for k in range(N_SKU)}
    bin_ = {k: {"percent_saved": rng.choice([0, 0, 5, 10, 15, 25])} for k in range(N_SKU)}
    picker = {k: {"name": "picker-%03d" % k} for k in range(N_PICKER)}
    skuc, binc, picc = {}, {}, {}
    lats = []
    for i in range(N_REQUESTS):
        items = [{"sku_id": c, "units": rng.randint(1, 5)} for c in rng.sample(range(N_SKU), rng.randint(2, MAX_ITEMS))]
        pl = {"picker_id": rng.randrange(N_PICKER), "items": items}
        store._load({"picklist:%d" % i: pl})
        auth._add("t", "u")
        before = store.ms
        store.ms += 54  # auth
        store.ms += 10  # picklist get
        if cache_picker:
            pid = pl["picker_id"]
            if pid not in picc:
                store.ms += 10 + 1
                picc[pid] = picker[pid]
        else:
            store.ms += 10
        missing = [it["sku_id"] for it in items if it["sku_id"] not in skuc or it["sku_id"] not in binc]
        if missing:
            keys = ["sku:%d" % m for m in missing] + ["bin:%d" % m for m in missing]
            store.ms += 10 + len(keys)  # get_many
            for k in keys:
                name, sid = k.split(":")
                (skuc if name == "sku" else binc)[int(sid)] = (sku if name == "sku" else bin_)[int(sid)]
        lats.append(store.ms - before)
    lats.sort()
    import math
    return lats[math.ceil(0.95*len(lats))-1], sum(1 for l in lats if l > 90)

print("unified batch only:        p95 =", run(False))
print("unified batch + picker:    p95 =", run(True))
